-- Pointer schema baseline: schema version 1.
--
-- A fresh database is created by applying this file inside the migration
-- runner's transaction (scripts/migrate.ts), which then records version 1 in
-- pointer_schema_versions. It was produced on 2026-11-14 by migrating an empty
-- PostgreSQL 17 database through every pre-release step and dumping the result
-- (pg_dump --schema-only), so it is exactly that schema. A fresh install has no
-- seeded rows.
--
-- Do not edit this file to change the schema. Add the next migration as
-- 0002_<name>.sql, raise LATEST_POINTER_SCHEMA_VERSION in
-- src/db/latest-schema.mjs, and update src/db/schema.ts to match.
--
-- Objects appear in dependency order: functions, tables, primary key and
-- unique constraints, indexes (several composite foreign keys reference unique
-- indexes), triggers, foreign keys, then privileges.

-- Functions

CREATE FUNCTION protect_model_observation_immutable_fields() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF ROW(NEW.snapshot_id, NEW.source_id, NEW.kind, NEW.native_id, NEW.raw_name, NEW.namespace, NEW.attributes, NEW.raw_payload, NEW.provenance, NEW.fetched_at)
     IS DISTINCT FROM
     ROW(OLD.snapshot_id, OLD.source_id, OLD.kind, OLD.native_id, OLD.raw_name, OLD.namespace, OLD.attributes, OLD.raw_payload, OLD.provenance, OLD.fetched_at) THEN
    RAISE EXCEPTION 'model observation facts are immutable';
  END IF;
  RETURN NEW;
END;
$$;

