CREATE TABLE api_keys (
    id text NOT NULL,
    user_id text NOT NULL,
    instance_id text NOT NULL,
    key_hash text NOT NULL,
    key_preview text NOT NULL,
    name text NOT NULL,
    allowed_models jsonb DEFAULT '["*"]'::jsonb,
    fallback_provider_id text,
    scopes jsonb DEFAULT '["read", "write"]'::jsonb,
    purpose text DEFAULT 'local_operator'::text NOT NULL,
    lifecycle text DEFAULT 'active'::text NOT NULL,
    managed_installation_id text,
    generation integer DEFAULT 1 NOT NULL,
    replacement_of_key_id text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    last_used timestamp with time zone,
    request_count integer DEFAULT 0,
    revoked boolean DEFAULT false,
    revoked_at timestamp with time zone,
    CONSTRAINT api_keys_generation_check CHECK ((generation > 0)),
    CONSTRAINT api_keys_lifecycle_check CHECK ((lifecycle = ANY (ARRAY['active'::text, 'pending'::text, 'retired'::text]))),
    CONSTRAINT api_keys_purpose_check CHECK ((purpose = ANY (ARRAY['local_operator'::text, 'internal_test'::text, 'managed_application'::text])))
);

