);

CREATE TABLE resolver_decisions (
    id text NOT NULL,
    resolver_run_id text NOT NULL,
    observation_id text NOT NULL,
    entity_id text,
    state text NOT NULL,
    method text NOT NULL,
    confidence numeric(5,4) NOT NULL,
    candidate_entity_ids jsonb DEFAULT '[]'::jsonb NOT NULL,
    evidence jsonb DEFAULT '[]'::jsonb NOT NULL,
    blockers jsonb DEFAULT '[]'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT chk_resolver_decision_confidence CHECK (((confidence >= (0)::numeric) AND (confidence <= (1)::numeric))),
    CONSTRAINT chk_resolver_decision_method CHECK ((method = ANY (ARRAY['native_id'::text, 'crosswalk'::text, 'approved_alias'::text, 'structured_match'::text, 'reviewed_override'::text, 'none'::text]))),
    CONSTRAINT chk_resolver_decision_state CHECK ((state = ANY (ARRAY['linked'::text, 'ambiguous'::text, 'unresolved'::text, 'rejected'::text])))
);

CREATE TABLE resolver_runs (
    id text NOT NULL,
    generation_id text,
    resolver_version text NOT NULL,
    status text DEFAULT 'running'::text NOT NULL,
    started_at timestamp with time zone DEFAULT now() NOT NULL,
    completed_at timestamp with time zone,
    stats jsonb DEFAULT '{}'::jsonb NOT NULL,
    error text,
    CONSTRAINT chk_resolver_run_status CHECK ((status = ANY (ARRAY['running'::text, 'completed'::text, 'failed'::text])))
);

CREATE TABLE source_records (
    id text NOT NULL,
    source_id text NOT NULL,
    record_key text NOT NULL,
    kind text NOT NULL,
    payload jsonb NOT NULL,
    provenance jsonb NOT NULL,
    fetched_at timestamp with time zone NOT NULL
);

CREATE TABLE source_snapshots (
    id text NOT NULL,
    generation_id text,
    source_id text NOT NULL,
    revision text NOT NULL,
    source_url text NOT NULL,
    license text NOT NULL,
    fetched_at timestamp with time zone NOT NULL,
    record_count integer NOT NULL,
    content_hash text NOT NULL,
    state text DEFAULT 'staged'::text NOT NULL,
    active boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT chk_source_snapshot_record_count CHECK ((record_count >= 0)),
    CONSTRAINT chk_source_snapshot_state CHECK ((state = ANY (ARRAY['staged'::text, 'validated'::text, 'active'::text, 'failed'::text, 'retired'::text])))
);

CREATE TABLE source_sync_states (
    source_id text NOT NULL,
    status text DEFAULT 'never_synced'::text NOT NULL,
    last_attempt_at timestamp with time zone,
    last_success_at timestamp with time zone,
    fetched_at timestamp with time zone,
    record_count integer DEFAULT 0 NOT NULL,
    error_code text,
    error_message text,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE system_settings (
    key text NOT NULL,
    value text NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE usage_logs (
    id text NOT NULL,
    api_key_id text,
    user_id text NOT NULL,
    model_id text NOT NULL,
    catalog_entity_id text,
    provider_id text NOT NULL,
    input_tokens integer,
    output_tokens integer,
    cached_tokens integer,
    reasoning_tokens integer,
    cache_creation_tokens integer,
    cache_read_tokens integer,
    cost_usd numeric,
    cost_status text DEFAULT 'unknown'::text NOT NULL,
    input_price_snapshot numeric,
    output_price_snapshot numeric,
    price_source text,
    latency_ms integer,
    ttfb_ms integer,
    generation_ms integer,
    tokens_per_second numeric,
    queue_time_ms integer,
    prompt_time_ms integer,
    completion_time_ms integer,
    processing_ms integer,
    status_code integer,
    error_type text,
    error_message text,
    outcome text DEFAULT 'success'::text NOT NULL,
    instance_id text,
    source text DEFAULT 'proxy'::text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    provider_account_id text,
    request_id text,
    upstream_error_code text,
    failure_receipt jsonb
);

CREATE TABLE users (
    id text NOT NULL,
    kind text DEFAULT 'local'::text NOT NULL,
    email text,
    name text NOT NULL,
    password_hash text,
    role text DEFAULT 'user'::text NOT NULL,
    external_issuer text,
    external_subject text,
    state text DEFAULT 'active'::text NOT NULL,
    avatar_url text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT users_external_identity_check CHECK ((((kind = 'external'::text) AND (external_issuer IS NOT NULL) AND (external_subject IS NOT NULL)) OR ((kind <> 'external'::text) AND (external_issuer IS NULL) AND (external_subject IS NULL)))),
    CONSTRAINT users_kind_check CHECK ((kind = ANY (ARRAY['local'::text, 'service'::text, 'external'::text]))),
    CONSTRAINT users_local_credentials_check CHECK (((kind <> 'local'::text) OR ((email IS NOT NULL) AND (password_hash IS NOT NULL)))),
    CONSTRAINT users_role_check CHECK ((role = ANY (ARRAY['admin'::text, 'user'::text]))),
    CONSTRAINT users_service_password_check CHECK (((kind <> 'service'::text) OR (password_hash IS NULL))),
    CONSTRAINT users_state_check CHECK ((state = ANY (ARRAY['active'::text, 'disabled'::text])))
);

